import { Component, For, onCleanup, onMount, useContext } from "solid-js";

import ActionHandler from "#core/ui/input/action-handler.js";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { LineGraph } from "#core/ui-next/components/line-graph.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { Tooltip, TooltipHorizontalPosition } from "#core/ui-next/components/tooltip.jsx";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";

import { VictoriesAltBase } from "#base/ui-next/screens/victories/victories-alt-base.js";
import { useVictoriesScreenContext, VictoryTabType } from "#base/ui-next/screens/victories/victories-screen-model.js";
import { VictoryRow } from "#base/ui-next/screens/victories/victory-tab-base.jsx";

export const EconomicVictoryTab: Component = () => {
	const model = useVictoriesScreenContext();

	const iterableItems: { name: string; description: string; value: AgeType }[] = [];
	for (const [key, value] of model.data.economicDetails.ageOptions.items.entries()) {
		iterableItems.push({ name: value.name, description: value.description, value: key });
	}

	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		hotkeyContext.registerNavtray("shell-action-1", "LOC_VICTORY_NAV_HELP_INSPECT");
		hotkeyContext.registerNavtray("shell-action-2", "LOC_VICTORY_NAV_HELP_AGE_TOOLTIP");
		hotkeyContext.registerNavtray("shell-action-3", "LOC_VICTORY_NAV_HELP_RULES");
		model.tabNavStartup(hotkeyContext);
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("shell-action-1");
		hotkeyContext.unregisterNavtray("shell-action-2");
		hotkeyContext.unregisterNavtray("shell-action-3");
		model.tabNavShutdown(hotkeyContext);
	});

	return (
		<VictoriesAltBase
			isScoreTab={false}
			backgroundImage="url(bg_victory_economic3)"
			backgroundClass="absolute inset-0 relative bg-cover bg-no-repeat opacity-30 pointer-events-none"
			headerText={model.data.economicDetails.headerText}
			victoryName="LOC_VICTORY_ECONOMIC_MODERN_NAME"
			titleColorClass={model.data.panels[1].titleColor}
			pointGoal={model.data.panels[1].goals.pointGoal}
			pointGoalLabel="LOC_VICTORY_GDP_NEEDED_TO_WIN"
			rulesText="LOC_VICTORIES_RULES_ECONOMIC"
			slotName="Economic"
			headerContent={() => (
				<div class="w-full h-full relative victories-military-left-line-header">
					<div class="relative ml-2 mt-2\.5 uppercase fxs-header self-end">
						<Dropdown
							defaultValue={model.data.economicDetails.ageOptions.selectedValue()}
							selectedItemTemplate={(value) => (
								<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
									<Tooltip.Trigger>
										<L10n.Compose
											text={model.data.economicDetails.ageOptions.items.get(value)?.name ?? ""}
										/>
									</Tooltip.Trigger>
									<Tooltip.Content>
										<Tooltip.Frame>
											<L10n.Compose
												text={
													model.data.economicDetails.ageOptions.items.get(value)
														?.description ?? ""
												}
											/>
										</Tooltip.Frame>
									</Tooltip.Content>
								</Tooltip>
							)}
							hotkey="shell-action-2"
							onItemSelected={(selected) => {
								model.data.economicDetails.ageOptions.setSelectedValue(selected as AgeType);
							}}
						>
							<For each={iterableItems}>
								{(value) => (
									<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
										<Tooltip.Trigger>
											<DropdownItem value={value.value}>
												<L10n.Compose text={value.name} />
											</DropdownItem>
										</Tooltip.Trigger>
										<Tooltip.Content>
											<Tooltip.Frame>
												<L10n.Compose text={value.description} />
											</Tooltip.Frame>
										</Tooltip.Content>
									</Tooltip>
								)}
							</For>
						</Dropdown>
					</div>
				</div>
			)}
			scrollAreaClass="victories-scroll-base w-full victories-econ-cols-1-and-2-and-4"
			rightContent={() => (
				<div class="h-full absolute inset-2">
					<LineGraph
						class={`opacity-100`}
						width={6}
						lines={model.data.economicDetails.currentChart.graphLines}
						maxX={model.data.economicDetails.currentChart.maxTurn}
						maxY={model.data.economicDetails.currentChart.graphTarget}
						minX={1} // Game technically starts on turn 1
						gridColorX={"rgb(255 255 255 / 30%)"}
						axisLabelX={Locale.compose("LOC_GENERIC_TURN")}
						axisLabelY={Locale.compose("LOC_VICTORY_ECONOMIC_GRAPH_TITLE")}
						axisNumberColor={"#b5b5b6"}
						axisLabelColor={"#848486"}
					/>
				</div>
			)}
		>
			<VSlot>
				<VSlot
					class="relative pointer-events-auto victories-economic-focus transition-opacity duration-150 ease-out flex flex-col"
					lockNavigation={true}
					autoFocus={!model.tooltipToggle}
				>
					<For each={model.data.economicDetails.playerDetails}>
						{(player, index) => (
							<VictoryRow
								rowId={index() + 1}
								playerInfo={player.playerInfo}
								divider={false}
								rowType={VictoryTabType.Economic}
								skipContentColumn={true}
								columnClassOverride="econ"
								omitBottomLine={true}
								activateInfo={(playerId: PlayerId) => {
									if (ActionHandler.isTouchActive) {
										model.focusPlayer(playerId, VictoryTabType.Economic);
										model.onGamepadInspectButton();
									}
								}}
							/>
						)}
					</For>
				</VSlot>
			</VSlot>
		</VictoriesAltBase>
	);
};
